func TestTheStreamForSeed0IsSplitmix64(emonT *testing.T) {
	var st *port.Cells = port.NewCells()
	splitmix.SmSeed(st, 0)
	var w0 int64 = splitmix.SmNext(st)
	port.AssertEqAt(emonT, splitmix.SmHi(w0), -501176263, "high half", 0)
	port.AssertEqAt(emonT, splitmix.SmLo(w0), 2065550767, "low half", 0)
	var w1 int64 = splitmix.SmNext(st)
	port.AssertEqAt(emonT, splitmix.SmHi(w1), 1853398634, "high half", 1)
	port.AssertEqAt(emonT, splitmix.SmLo(w1), -1581685260, "low half", 1)
	var w2 int64 = splitmix.SmNext(st)
	port.AssertEqAt(emonT, splitmix.SmHi(w2), 113532184, "high half", 2)
	port.AssertEqAt(emonT, splitmix.SmLo(w2), -2146876081, "low half", 2)
	var w3 int64 = splitmix.SmNext(st)
	port.AssertEqAt(emonT, splitmix.SmHi(w3), -125060952, "high half", 3)
	port.AssertEqAt(emonT, splitmix.SmLo(w3), 1917616620, "low half", 3)
}

