func TestBelowIsInRangeAndAdvances(emonT *testing.T) {
	var st *port.Cells = port.NewCells()
	var i int32 = 0
	splitmix.SmSeed(st, 0)
	port.AssertEq(emonT, splitmix.SmBelow(st, 1000), 516, "first below-1000 of seed 0")
	port.AssertEq(emonT, splitmix.SmBelow(st, 0), 0, "n = 0 answers 0")
	port.AssertEq(emonT, splitmix.SmBelow(st, -5), 0, "n < 0 answers 0")
	splitmix.SmSeed(st, 99)
	for i < 200 {
		port.AssertThatAt(emonT, splitmix.SmBelow(st, 7) >= 0, "non-negative", i)
		i += 1
	}
}

func TestAReseedRestartsTheStream(emonT *testing.T) {
	var st *port.Cells = port.NewCells()
	splitmix.SmSeed(st, 5)
	var w0 int64 = splitmix.SmNext(st)
	var w1 int64 = splitmix.SmNext(st)
	splitmix.SmSeed(st, 5)
	port.AssertEq64(emonT, splitmix.SmNext(st), w0, "same seed, same first word")
	port.AssertEq64(emonT, splitmix.SmNext(st), w1, "and the same second word")
	port.AssertThat(emonT, w0 != w1, "and the two differ")
}
